import{_ as e,o as a,c as d,an as i}from"./chunks/framework.CfibuiLs.js";const y=JSON.parse('{"title":"Cheatsheet","description":"","frontmatter":{},"headers":[],"relativePath":"cheatsheet.md","filePath":"cheatsheet.md","lastUpdated":null}'),n={name:"cheatsheet.md"};function r(l,t,o,g,s,c){return a(),d("div",null,[...t[0]||(t[0]=[i('<h1 id="Cheatsheet" tabindex="-1">Cheatsheet <a class="header-anchor" href="#Cheatsheet" aria-label="Permalink to &quot;Cheatsheet {#Cheatsheet}&quot;">​</a></h1><p>Quick reference for common EEG processing tasks in EegFun.jl.</p><h2 id="Data-Import" tabindex="-1">Data Import <a class="header-anchor" href="#Data-Import" aria-label="Permalink to &quot;Data Import {#Data-Import}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;">I want to...</th><th style="text-align:right;">Function</th></tr></thead><tbody><tr><td style="text-align:right;">Load a BioSemi .bdf file</td><td style="text-align:right;"><code>EegFun.read_raw_data(&quot;file.bdf&quot;)</code></td></tr><tr><td style="text-align:right;">Load a BrainVision file</td><td style="text-align:right;"><code>EegFun.read_raw_data(&quot;file.vhdr&quot;)</code></td></tr><tr><td style="text-align:right;">Load an EEGLAB file</td><td style="text-align:right;"><code>EegFun.read_eeglab(&quot;file.set&quot;)</code></td></tr><tr><td style="text-align:right;">Load a FieldTrip .mat file</td><td style="text-align:right;"><code>EegFun.read_fieldtrip(&quot;file.mat&quot;)</code></td></tr><tr><td style="text-align:right;">Load a channel layout</td><td style="text-align:right;"><code>EegFun.read_layout(&quot;layout.csv&quot;)</code></td></tr><tr><td style="text-align:right;">Create EegFun data structure</td><td style="text-align:right;"><code>EegFun.create_eegfun_data(raw, layout)</code></td></tr></tbody></table><h2 id="Data-Persistence-JLD2" tabindex="-1">Data Persistence (JLD2) <a class="header-anchor" href="#Data-Persistence-JLD2" aria-label="Permalink to &quot;Data Persistence (JLD2) {#Data-Persistence-JLD2}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;">I want to...</th><th style="text-align:right;">Function</th></tr></thead><tbody><tr><td style="text-align:right;">Save data to JLD2</td><td style="text-align:right;"><code>jldsave(&quot;file.jld2&quot;; data = dat)</code></td></tr><tr><td style="text-align:right;">Load data from JLD2</td><td style="text-align:right;"><code>load(&quot;file.jld2&quot;, &quot;data&quot;)</code></td></tr><tr><td style="text-align:right;">Smart-load EegFun data</td><td style="text-align:right;"><code>EegFun.read_data(&quot;file.jld2&quot;)</code></td></tr><tr><td style="text-align:right;">Batch load all matching files</td><td style="text-align:right;"><code>EegFun.read_all_data(&quot;dir/pattern&quot;)</code></td></tr><tr><td style="text-align:right;">Group loaded data by condition</td><td style="text-align:right;"><code>EegFun.group_by_condition(data)</code></td></tr></tbody></table><h2 id="Preprocessing" tabindex="-1">Preprocessing <a class="header-anchor" href="#Preprocessing" aria-label="Permalink to &quot;Preprocessing {#Preprocessing}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;">I want to...</th><th style="text-align:right;">Function</th></tr></thead><tbody><tr><td style="text-align:right;">Rereference to average</td><td style="text-align:right;"><code>EegFun.rereference!(dat, :avg)</code></td></tr><tr><td style="text-align:right;">Rereference to specific channels</td><td style="text-align:right;"><code>EegFun.rereference!(dat, [:M1, :M2])</code></td></tr><tr><td style="text-align:right;">High-pass filter</td><td style="text-align:right;"><code>EegFun.highpass_filter!(dat, 0.1)</code></td></tr><tr><td style="text-align:right;">Low-pass filter</td><td style="text-align:right;"><code>EegFun.lowpass_filter!(dat, 30.0)</code></td></tr><tr><td style="text-align:right;">Bandpass filter</td><td style="text-align:right;"><code>EegFun.bandpass_filter!(dat, 0.1, 30.0)</code></td></tr><tr><td style="text-align:right;">Resample data</td><td style="text-align:right;"><code>EegFun.resample!(dat, 256)</code></td></tr><tr><td style="text-align:right;">Apply baseline correction</td><td style="text-align:right;"><code>EegFun.baseline!(dat, (-0.2, 0.0))</code></td></tr><tr><td style="text-align:right;">Create channel difference</td><td style="text-align:right;"><code>EegFun.channel_difference!(dat, channel_selection1=channels([:C3]), channel_selection2=channels([:C4]), channel_out=:laterality)</code></td></tr><tr><td style="text-align:right;">Average channels into ROI</td><td style="text-align:right;"><code>EegFun.channel_average!(dat, channel_selections=[channels([:Fz, :Cz, :Pz])], output_labels=[:midline])</code></td></tr><tr><td style="text-align:right;">Delete channels</td><td style="text-align:right;"><code>EegFun.channel_delete!(dat, channels([:M1, :M2]))</code></td></tr><tr><td style="text-align:right;">Mark extreme values</td><td style="text-align:right;"><code>EegFun.is_extreme_value!(dat, 100)</code></td></tr><tr><td style="text-align:right;">View trigger counts</td><td style="text-align:right;"><code>EegFun.trigger_count(dat)</code></td></tr><tr><td style="text-align:right;">Search trigger sequences</td><td style="text-align:right;"><code>EegFun.search_sequence(dat.data.trigger, [1, 2])</code></td></tr></tbody></table><h2 id="ICA" tabindex="-1">ICA <a class="header-anchor" href="#ICA" aria-label="Permalink to &quot;ICA {#ICA}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;">I want to...</th><th style="text-align:right;">Function</th></tr></thead><tbody><tr><td style="text-align:right;">Run ICA decomposition</td><td style="text-align:right;"><code>EegFun.run_ica(dat)</code></td></tr><tr><td style="text-align:right;">Identify EOG components</td><td style="text-align:right;"><code>EegFun.identify_eog_components(dat, ica)</code></td></tr><tr><td style="text-align:right;">Identify ECG components</td><td style="text-align:right;"><code>EegFun.identify_ecg_components(dat, ica)</code></td></tr><tr><td style="text-align:right;">Identify line noise components</td><td style="text-align:right;"><code>EegFun.identify_line_noise_components(dat, ica)</code></td></tr><tr><td style="text-align:right;">Remove components</td><td style="text-align:right;"><code>EegFun.remove_ica_components!(dat, ica, component_selection=components([1, 3]))</code></td></tr><tr><td style="text-align:right;">Restore components</td><td style="text-align:right;"><code>EegFun.restore_ica_components!(dat, ica, component_selection=components([1]))</code></td></tr></tbody></table><h2 id="Epoching" tabindex="-1">Epoching <a class="header-anchor" href="#Epoching" aria-label="Permalink to &quot;Epoching {#Epoching}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;">I want to...</th><th style="text-align:right;">Function</th></tr></thead><tbody><tr><td style="text-align:right;">Define epoch conditions</td><td style="text-align:right;"><code>cfg = [EegFun.EpochCondition(name=&quot;Cond1&quot;, trigger_sequences=[[1]])]</code></td></tr><tr><td style="text-align:right;">Dry-run epoch count</td><td style="text-align:right;"><code>EegFun.epochs_count(dat, cfg, (-0.2, 1.0))</code></td></tr><tr><td style="text-align:right;">Extract epochs</td><td style="text-align:right;"><code>EegFun.extract_epochs(dat, cfg, (-0.2, 1.0))</code></td></tr><tr><td style="text-align:right;">Print epoch count table</td><td style="text-align:right;"><code>EegFun.epochs_table(epochs)</code></td></tr><tr><td style="text-align:right;">Baseline correct epochs</td><td style="text-align:right;"><code>EegFun.baseline!(epochs, (-0.2, 0.0))</code></td></tr><tr><td style="text-align:right;">Detect bad epochs automatically</td><td style="text-align:right;"><code>EegFun.detect_bad_epochs_automatic(epochs)</code></td></tr><tr><td style="text-align:right;">Detect bad epochs interactively</td><td style="text-align:right;"><code>EegFun.detect_bad_epochs_interactive(epochs)</code></td></tr><tr><td style="text-align:right;">Reject marked epochs</td><td style="text-align:right;"><code>EegFun.reject_epochs(epochs)</code></td></tr><tr><td style="text-align:right;">Log before/after rejection table</td><td style="text-align:right;"><code>EegFun.log_epochs_table(before, after)</code></td></tr><tr><td style="text-align:right;">Repair artifacts (interpolation)</td><td style="text-align:right;"><code>EegFun.repair_artifacts(epochs)</code></td></tr></tbody></table><h2 id="ERP-Operations" tabindex="-1">ERP Operations <a class="header-anchor" href="#ERP-Operations" aria-label="Permalink to &quot;ERP Operations {#ERP-Operations}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;">I want to...</th><th style="text-align:right;">Function</th></tr></thead><tbody><tr><td style="text-align:right;">Average epochs into ERPs</td><td style="text-align:right;"><code>EegFun.average_epochs(epochs)</code></td></tr><tr><td style="text-align:right;">Combine conditions</td><td style="text-align:right;"><code>EegFun.condition_combine(erps, [[1, 2]])</code></td></tr><tr><td style="text-align:right;">Subtract conditions</td><td style="text-align:right;"><code>EegFun.condition_difference(erps, [(1, 2)])</code></td></tr><tr><td style="text-align:right;">Average conditions</td><td style="text-align:right;"><code>EegFun.condition_average(erps, [[1, 2]])</code></td></tr><tr><td style="text-align:right;">Compute grand average</td><td style="text-align:right;"><code>EegFun.grand_average(all_erps)</code></td></tr><tr><td style="text-align:right;">Jackknife average</td><td style="text-align:right;"><code>EegFun.jackknife_average(all_erps)</code></td></tr><tr><td style="text-align:right;">Compute GFP</td><td style="text-align:right;"><code>EegFun.gfp(erps)</code></td></tr><tr><td style="text-align:right;">Realign epochs to response trigger</td><td style="text-align:right;"><code>EegFun.realign!(epochs, [201])</code></td></tr><tr><td style="text-align:right;">Compute LRP</td><td style="text-align:right;"><code>EegFun.lrp(erps, channel_selection1=channels([:C3]), channel_selection2=channels([:C4]))</code></td></tr></tbody></table><h2 id="ERP-Measurements-and-Export" tabindex="-1">ERP Measurements &amp; Export <a class="header-anchor" href="#ERP-Measurements-and-Export" aria-label="Permalink to &quot;ERP Measurements &amp; Export {#ERP-Measurements-and-Export}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;">I want to...</th><th style="text-align:right;">Function</th></tr></thead><tbody><tr><td style="text-align:right;">Extract mean amplitude</td><td style="text-align:right;"><code>EegFun.erp_measurements(&quot;erps&quot;, &quot;mean_amplitude&quot;, analysis_interval=(0.3, 0.5))</code></td></tr><tr><td style="text-align:right;">Extract peak amplitude</td><td style="text-align:right;"><code>EegFun.erp_measurements(&quot;erps&quot;, &quot;max_peak_amplitude&quot;, analysis_interval=(0.3, 0.5))</code></td></tr><tr><td style="text-align:right;">Extract peak latency</td><td style="text-align:right;"><code>EegFun.erp_measurements(&quot;erps&quot;, &quot;max_peak_latency&quot;, analysis_interval=(0.3, 0.5))</code></td></tr><tr><td style="text-align:right;">Explore measurements in GUI</td><td style="text-align:right;"><code>EegFun.plot_erp_measurement_gui(erps)</code></td></tr></tbody></table><h2 id="Time-Frequency-Analysis" tabindex="-1">Time-Frequency Analysis <a class="header-anchor" href="#Time-Frequency-Analysis" aria-label="Permalink to &quot;Time-Frequency Analysis {#Time-Frequency-Analysis}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;">I want to...</th><th style="text-align:right;">Function</th></tr></thead><tbody><tr><td style="text-align:right;">Morlet wavelet decomposition</td><td style="text-align:right;"><code>EegFun.tf_morlet(epochs, frequencies=4:1:30, n_cycles=3)</code></td></tr><tr><td style="text-align:right;">Multitaper decomposition</td><td style="text-align:right;"><code>EegFun.tf_multitaper(epochs, frequencies=4:1:30)</code></td></tr><tr><td style="text-align:right;">STFT decomposition</td><td style="text-align:right;"><code>EegFun.tf_stft(epochs, frequencies=4:1:30)</code></td></tr><tr><td style="text-align:right;">Baseline correct TF data</td><td style="text-align:right;"><code>EegFun.tf_baseline!(tf, (-0.2, 0.0); method=:db)</code></td></tr><tr><td style="text-align:right;">TF channel average</td><td style="text-align:right;"><code>EegFun.channel_average!(tf, channel_selections=[channels([:Fz, :Cz])], output_labels=[:frontal])</code></td></tr><tr><td style="text-align:right;">TF channel difference</td><td style="text-align:right;"><code>EegFun.channel_difference!(tf, channel_selection1=channels([:C3]), channel_selection2=channels([:C4]))</code></td></tr><tr><td style="text-align:right;">TF condition difference</td><td style="text-align:right;"><code>EegFun.condition_difference(tf_data, [(1, 2)])</code></td></tr><tr><td style="text-align:right;">TF condition average</td><td style="text-align:right;"><code>EegFun.condition_average(tf_data, [[1, 2]])</code></td></tr><tr><td style="text-align:right;">TF grand average</td><td style="text-align:right;"><code>EegFun.grand_average(all_tf)</code></td></tr></tbody></table><h2 id="Statistics" tabindex="-1">Statistics <a class="header-anchor" href="#Statistics" aria-label="Permalink to &quot;Statistics {#Statistics}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;">I want to...</th><th style="text-align:right;">Function</th></tr></thead><tbody><tr><td style="text-align:right;">Prepare group data for stats</td><td style="text-align:right;"><code>EegFun.prepare_stats(&quot;erps&quot;, :paired, condition_selection=conditions([1, 2]))</code></td></tr><tr><td style="text-align:right;">Run analytic t-test</td><td style="text-align:right;"><code>EegFun.analytic_test(stat_data)</code></td></tr><tr><td style="text-align:right;">Run permutation test</td><td style="text-align:right;"><code>EegFun.permutation_test(stat_data, n_permutations=1000)</code></td></tr><tr><td style="text-align:right;">Test decoding against chance</td><td style="text-align:right;"><code>EegFun.test_against_chance(decoded_list)</code></td></tr><tr><td style="text-align:right;">Cluster permutation (decoding)</td><td style="text-align:right;"><code>EegFun.test_against_chance_cluster(decoded_list)</code></td></tr></tbody></table><h2 id="Plotting" tabindex="-1">Plotting <a class="header-anchor" href="#Plotting" aria-label="Permalink to &quot;Plotting {#Plotting}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;">I want to...</th><th style="text-align:right;">Function</th></tr></thead><tbody><tr><td style="text-align:right;">Browse continuous data</td><td style="text-align:right;"><code>EegFun.plot_databrowser(dat)</code></td></tr><tr><td style="text-align:right;">Browse with ICA</td><td style="text-align:right;"><code>EegFun.plot_databrowser(dat, ica)</code></td></tr><tr><td style="text-align:right;">Plot ERPs</td><td style="text-align:right;"><code>EegFun.plot_erp(erps, channel_selection=channels(:Pz))</code></td></tr><tr><td style="text-align:right;">Plot topography</td><td style="text-align:right;"><code>EegFun.plot_topography(erps, interval_selection=times(0.3, 0.5))</code></td></tr><tr><td style="text-align:right;">Plot ERP statistics</td><td style="text-align:right;"><code>EegFun.plot_erp_stats(result, channel_selection=channels(:Pz))</code></td></tr><tr><td style="text-align:right;">Plot TF power</td><td style="text-align:right;"><code>EegFun.plot_tf(tf, channel_selection=channels(:Cz))</code></td></tr><tr><td style="text-align:right;">Plot TF statistics</td><td style="text-align:right;"><code>EegFun.plot_tf_stats(result, channel_selection=channels(:Cz))</code></td></tr><tr><td style="text-align:right;">Plot TF topography stats</td><td style="text-align:right;"><code>EegFun.plot_topography_stats(result, freq_range=(8.0, 12.0))</code></td></tr><tr><td style="text-align:right;">Plot ICA components</td><td style="text-align:right;"><code>EegFun.plot_topography(ica)</code></td></tr><tr><td style="text-align:right;">Plot epochs grid</td><td style="text-align:right;"><code>EegFun.plot_epochs(epochs)</code></td></tr><tr><td style="text-align:right;">Plot ERP image</td><td style="text-align:right;"><code>EegFun.plot_erp_image(epochs, channel_selection=channels(:Pz))</code></td></tr><tr><td style="text-align:right;">Plot GFP</td><td style="text-align:right;"><code>EegFun.plot_gfp(erps)</code></td></tr><tr><td style="text-align:right;">Plot channel layout</td><td style="text-align:right;"><code>EegFun.plot_layout_2d(layout)</code></td></tr><tr><td style="text-align:right;">Plot artifact detection</td><td style="text-align:right;"><code>EegFun.plot_artifact_detection(epochs)</code></td></tr><tr><td style="text-align:right;">Plot frequency spectrum</td><td style="text-align:right;"><code>EegFun.plot_channel_spectrum(dat)</code></td></tr><tr><td style="text-align:right;">Plot filter response</td><td style="text-align:right;"><code>EegFun.plot_filter_response(dat)</code></td></tr><tr><td style="text-align:right;">Plot decoding results</td><td style="text-align:right;"><code>EegFun.plot_decoding(decoded)</code></td></tr><tr><td style="text-align:right;">Plot RSA results</td><td style="text-align:right;"><code>EegFun.plot_rsa(rsa_result)</code></td></tr></tbody></table><h2 id="Selection-Helpers" tabindex="-1">Selection Helpers <a class="header-anchor" href="#Selection-Helpers" aria-label="Permalink to &quot;Selection Helpers {#Selection-Helpers}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;">I want to select...</th><th style="text-align:right;">Helper</th></tr></thead><tbody><tr><td style="text-align:right;">Specific channels</td><td style="text-align:right;"><code>EegFun.channels([:Fz, :Cz, :Pz])</code></td></tr><tr><td style="text-align:right;">All channels except</td><td style="text-align:right;"><code>EegFun.channels_not([:M1, :M2])</code></td></tr><tr><td style="text-align:right;">Channel range</td><td style="text-align:right;"><code>EegFun.channels(1:32)</code></td></tr><tr><td style="text-align:right;">Specific conditions</td><td style="text-align:right;"><code>EegFun.conditions([1, 2])</code></td></tr><tr><td style="text-align:right;">All conditions except</td><td style="text-align:right;"><code>EegFun.conditions_not([3])</code></td></tr><tr><td style="text-align:right;">Time interval</td><td style="text-align:right;"><code>EegFun.times((0.3, 0.5))</code></td></tr><tr><td style="text-align:right;">Specific participants</td><td style="text-align:right;"><code>EegFun.participants([1, 2, 3])</code></td></tr><tr><td style="text-align:right;">All participants except</td><td style="text-align:right;"><code>EegFun.participants_not([10])</code></td></tr><tr><td style="text-align:right;">Specific samples</td><td style="text-align:right;"><code>EegFun.samples(:is_extreme_value_100)</code></td></tr><tr><td style="text-align:right;">All samples except</td><td style="text-align:right;"><code>EegFun.samples_not(:is_extreme_value_100)</code></td></tr><tr><td style="text-align:right;">Specific components</td><td style="text-align:right;"><code>EegFun.components([1, 3, 5])</code></td></tr></tbody></table>',24)])])}const x=e(n,[["render",r]]);export{y as __pageData,x as default};
